palindrome:
def is_palindrome(t):
    s=[c.lower() for c in t if c.isalnum()]
    return s==s[::-1]

merge-intervals:
def merge_intervals(items):
    r=[]
    for a,b in sorted(items):
        if r and a<=r[-1][1]:
            r[-1][1]=max(r[-1][1],b)
        else:
            r.append([a,b])
    return r

lru-cache:
from collections import OrderedDict
class LRUCache:
    def __init__(self,c):
        self.c=c;self.d=OrderedDict()
    def get(self,k):
        if k not in self.d: return -1
        self.d.move_to_end(k);return self.d[k]
    def put(self,k,v):
        self.d[k]=v;self.d.move_to_end(k)
        if len(self.d)>self.c: self.d.popitem(last=False)

topo-sort:
def topo_sort(g):
    o=[];s={}
    def v(n):
        if s.get(n)==1: raise ValueError
        if s.get(n)==2: return
        s[n]=1
        for d in g.get(n,[]): v(d)
        s[n]=2;o.append(n)
    for n in g: v(n)
    return o

parse-csv-line:
def parse_csv_line(l):
    r=[];f='';q=False;i=0
    while i<len(l):
        c=l[i]
        if q and c=='"' and l[i+1:i+2]=='"':
            f+='"';i+=1
        elif c=='"':
            q=not q
        elif c==',' and not q:
            r.append(f);f=''
        else:
            f+=c
        i+=1
    r.append(f)
    return r

