import heapq
def shortest_path(g,s,t):
    d={s:0};h=[(0,s)]
    while h:
        c,n=heapq.heappop(h)
        if n==t: return c
        for m,w in g.get(n,{}).items():
            if c+w<d.get(m,float('inf')):
                d[m]=c+w;heapq.heappush(h,(c+w,m))
    return None

